type intakeGeographyData struct {
	Geo   map[string][][][2]float64 `json:"geo"`
	Lakes [][][2]float64            `json:"lakes"`
}

var intakeGeoOnce sync.Once
var intakeGeoData intakeGeographyData
var intakeGeoError error

func intakeGeography() (intakeGeographyData, error) {
	intakeGeoOnce.Do(func() { intakeGeoError = json.Unmarshal([]byte(intakeGeoDataJSON), &intakeGeoData) })
	return intakeGeoData, intakeGeoError
}

type intakeMapPoint struct {
	ID       string   `json:"id,omitempty"`
	Name     string   `json:"name"`
	Lon      *float64 `json:"lon"`
	Lat      *float64 `json:"lat"`
	Kind     string   `json:"kind,omitempty"`
	Label    *bool    `json:"label,omitempty"`
	LabelPos string   `json:"labelPos,omitempty"`
}
type intakeMapSource struct {
	Type         string           `json:"type"`
	ID           string           `json:"id,omitempty"`
	X            float64          `json:"x"`
	Y            float64          `json:"y"`
	W            float64          `json:"w"`
	Region       string           `json:"region,omitempty"`
	Pitch        float64          `json:"pitch,omitempty"`
	DotInk       string           `json:"dotInk,omitempty"`
	Points       []intakeMapPoint `json:"points,omitempty"`
	SourceHeight float64          `json:"_h,omitempty"`
}
type intakeMapPanel struct {
	L0, L1, A0, A1, Cos, X, W, H, KX, KY float64
	Polys, Holes                         [][][2]float64
	Inset                                bool
}
type intakeMapDot struct{ X, Y, Size float64 }

func intakeMapPanels(n intakeMapSource) ([]intakeMapPanel, error) {
	data, e := intakeGeography()
	if e != nil {
		return nil, e
	}
	panels := []intakeMapPanel{{L0: -125, L1: -66, A0: 24.5, A1: 49.5, Cos: .788, W: n.W, Polys: data.Geo["US"], Holes: data.Lakes}}
	if n.Region == "americas-uk" {
		main := n.W * .74
		inset := n.W - main - 18
		if inset <= 0 {
			return nil, fmt.Errorf("scene.dotmap_inset_does_not_fit")
		}
		polys := append(append([][][2]float64{}, data.Geo["US"]...), data.Geo["CA"]...)
		panels = []intakeMapPanel{{L0: -125, L1: -66, A0: 7.5, A1: 49.5, Cos: .87, W: main, Polys: polys, Holes: data.Lakes}, {L0: -6.4, L1: 2.4, A0: 49.6, A1: 59, Cos: .6, X: main + 18, W: inset, Polys: data.Geo["GB"], Inset: true}}
	}
	for i := range panels {
		p := &panels[i]
		p.KX = p.W / (p.L1 - p.L0)
		p.KY = p.KX / p.Cos
		p.H = (p.A1 - p.A0) * p.KY
	}
	return panels, nil
}
func intakeMapInside(poly [][2]float64, lon, lat float64) bool {
	inside := false
	for i, j := 0, len(poly)-1; i < len(poly); j, i = i, i+1 {
		a, b := poly[i], poly[j]
		if (a[1] > lat) != (b[1] > lat) && lon < (b[0]-a[0])*(lat-a[1])/(b[1]-a[1])+a[0] {
			inside = !inside
		}
	}
	return inside
}
func intakeMapLand(p intakeMapPanel, lon, lat float64) bool {
	land := false
	for _, poly := range p.Polys {
		if intakeMapInside(poly, lon, lat) {
			land = true
			break
		}
	}
	if !land {
		return false
	}
	for _, hole := range p.Holes {
		if intakeMapInside(hole, lon, lat) {
			return false
		}
	}
	return true
}
func intakeMapLocation(panels []intakeMapPanel, lon, lat float64) (float64, float64, error) {
	for _, p := range panels {
		if lon >= p.L0 && lon <= p.L1 && lat >= p.A0 && lat <= p.A1 {
			return p.X + (lon-p.L0)*p.KX, (p.A1 - lat) * p.KY, nil
		}
	}
	return 0, 0, fmt.Errorf("scene.dotmap_point_outside_supported_panels: %.4f,%.4f", lon, lat)
}

func (r *renderer) planIntakeGeographyScene(id string, raw json.RawMessage, ctx SceneContext) (*scenePlan, bool, error) {
	var head struct {
		Type string `json:"type"`
	}
	if e := json.Unmarshal(raw, &head); e != nil {
		return nil, false, e
	}
	if head.Type != "dotmap" {
		return nil, false, nil
	}
	var n intakeMapSource
	if e := primitiveDecode(raw, &n, "region pitch dotInk points _h"); e != nil {
		return nil, true, e
	}
	if !intakeFinite(n.X, n.Y, n.W, n.Pitch, n.SourceHeight) || n.W <= 0 || n.W > 1920 || math.Abs(n.X) > 3840 || math.Abs(n.Y) > 2160 {
		return nil, true, fmt.Errorf("scene.invalid_dotmap_geometry: %s", id)
	}
	if n.Region != "" && n.Region != "us" && n.Region != "americas-uk" {
		return nil, true, fmt.Errorf("scene.unsupported_dotmap_region: %s", n.Region)
	}
	if n.Pitch == 0 {
		n.Pitch = 6
	}
	if n.Pitch < 3 || n.Pitch > 36 || len(n.Points) > 128 {
		return nil, true, fmt.Errorf("scene.dotmap_resource_budget: %s", id)
	}
	panels, e := intakeMapPanels(n)
	if e != nil {
		return nil, true, e
	}
	ink := "CED7E6"
	if n.DotInk != "" {
		ink, e = r.sceneColor("light", n.DotInk)
		if e != nil {
			return nil, true, e
		}
	}
	height := 0.
	var dots []intakeMapDot
	var svg strings.Builder
	budget := 0
	for _, pn := range panels {
		height = math.Max(height, pn.H)
		if pn.Inset {
			fmt.Fprintf(&svg, `<rect x="%g" y="-6" width="%g" height="%g" fill="none" stroke="#CED7E6" stroke-width="0.75"/>`, pn.X-6, pn.W+12, pn.H+12)
		}
		pitch := n.Pitch
		if pn.Inset {
			pitch *= .75
		}
		ds := 2.
		if pitch >= 9 {
			ds = 3
		} else if pitch >= 6 {
			ds = 2.4
		}
		for gy := 0.; gy <= pn.H; gy += pitch {
			for gx := 0.; gx <= pn.W; gx += pitch {
				budget++
				if budget > 40000 {
					return nil, true, fmt.Errorf("scene.dotmap_sample_budget: %s", id)
				}
				if intakeMapLand(pn, pn.L0+gx/pn.KX, pn.A1-gy/pn.KY) {
					x, y := math.Round((pn.X+gx-ds/2)*10)/10, math.Round((gy-ds/2)*10)/10
					dots = append(dots, intakeMapDot{x, y, ds})
					fmt.Fprintf(&svg, `<rect x="%.1f" y="%.1f" width="%g" height="%g" fill="#%s"/>`, x, y, ds, ds, ink)
				}
			}
		}
	}
	view := Rect{-2, -2, n.W + 4, height + 4}
	if n.Region == "americas-uk" {
		view = Rect{-2, -7, n.W + 9, height + 14}
	}
	b := Rect{n.X + view.X, n.Y + view.Y, view.W, view.H}
	imageProps, e := intakeMapPicture(id+".map", b, view, dots, panels, ink, svg.String())
	if e != nil {
		return nil, true, e
	}
	p := &scenePlan{ID: id, Bounds: b, Items: []sceneItem{{Image: imageProps}}}
	keys, e := primitiveArrayKeys(ctx, "/points", len(n.Points))
	if e != nil {
		return nil, true, e
	}
	seen := map[string]bool{}
	for i, point := range n.Points {
		key := keys[i]
		if point.ID != "" {
			if ctx.Keys != nil && point.ID != key {
				return nil, true, fmt.Errorf("scene.conflicting_array_key: %s", id)
			}
			key = point.ID
		}
		if !validPartKey(key) || seen[key] {
			return nil, true, fmt.Errorf("scene.invalid_or_duplicate_key: %s", key)
		}
		seen[key] = true
		if point.Lon == nil || point.Lat == nil || !intakeFinite(*point.Lon, *point.Lat) || strings.TrimSpace(point.Name) == "" {
			return nil, true, fmt.Errorf("scene.invalid_dotmap_point: %s.%s", id, key)
		}
		if point.Kind != "" && point.Kind != "office" && point.Kind != "hub" {
			return nil, true, fmt.Errorf("scene.unsupported_dotmap_point_kind: %s", point.Kind)
		}
		pos := point.LabelPos
		if pos == "" {
			pos = "r"
		}
		if pos != "l" && pos != "r" && pos != "t" && pos != "b" {
			return nil, true, fmt.Errorf("scene.invalid_dotmap_label_position: %s", pos)
		}
		x, y, e := intakeMapLocation(panels, *point.Lon, *point.Lat)
		if e != nil {
			return nil, true, e
		}
		x += n.X
		y += n.Y
		hub := point.Kind == "hub"
		fill, line, weight, size := "070154", "", 0., 10.
		if hub {
			fill, line, weight, size = "FFFFFF", "0047FF", 2, 9
		}
		pre := id + ".points." + key
		if e = r.diagramShape(p, pre+".marker", Rect{x - size/2, y - size/2, size, size}, pptx.ShapeTypeEllipse, fill, line, weight, "solid", nil); e != nil {
			return nil, true, e
		}
		if point.Label != nil && !*point.Label {
			continue
		}
		lx, ly, align := x+9, y-7, "left"
		if pos == "l" {
			lx, align = x-129, "right"
		}
		if pos == "t" || pos == "b" {
			lx, align = x-60, "center"
			if pos == "t" {
				ly = y - 21
			} else {
				ly = y + 7
			}
		}
		color := "#070154"
		if hub {
			color = "#0047FF"
		}
		if e = r.diagramText(p, pre+".label", point.Name, "label", Rect{lx, ly, 120, 0}, "light", color, align, 600, false); e != nil {
			return nil, true, e
		}
	}
	p.Warnings = append(p.Warnings, "Dotmap geography is a frozen shared SVG with PNG compatibility fallback; point markers and labels are native editable objects. Geographic attribution: US Census/us-atlas and Natural Earth/world-atlas public domain; frozen data SHA256="+intakeGeoDataSHA256)
	diagramFinish(p, "dotmap")
	for i := range p.Groups {
		if p.Groups[i].ID == id {
			p.Groups[i].Contract = IntakeGeographyContract
		}
	}
	return p, true, nil
}

func intakeMapPicture(id string, b, view Rect, dots []intakeMapDot, panels []intakeMapPanel, ink, body string) (*pptx.ImageProps, error) {
	scale := 3.
	w, h := int(math.Ceil(view.W*scale)), int(math.Ceil(view.H*scale))
	if w <= 0 || h <= 0 || int64(w)*int64(h) > 16_000_000 {
		return nil, fmt.Errorf("scene.dotmap_raster_budget")
	}
	img := image.NewNRGBA(image.Rect(0, 0, w, h))
	hex, e := strconv.ParseUint(ink, 16, 24)
	if e != nil {
		return nil, e
	}
	rgb := color.NRGBA{R: byte(hex >> 16), G: byte(hex >> 8), B: byte(hex), A: 255}
	paint := func(x, y, w, h float64, c color.NRGBA) {
		rr := image.Rect(int(math.Round((x-view.X)*scale)), int(math.Round((y-view.Y)*scale)), int(math.Round((x+w-view.X)*scale)), int(math.Round((y+h-view.Y)*scale)))
		draw.Draw(img, rr, &image.Uniform{C: c}, image.Point{}, draw.Src)
	}
	for _, dot := range dots {
		paint(dot.X, dot.Y, dot.Size, dot.Size, color.NRGBA{R: rgb.R, G: rgb.G, B: rgb.B, A: 255})
	}
	for _, pn := range panels {
		if pn.Inset {
			c := color.NRGBA{R: 206, G: 215, B: 230, A: 255}
			x, y, w, h := pn.X-6, -6., pn.W+12, pn.H+12
			paint(x, y, w, .75, c)
			paint(x, y+h-.75, w, .75, c)
			paint(x, y, .75, h, c)
			paint(x+w-.75, y, .75, h, c)
		}
	}
	fallback, e := primitivePNG(img)
	if e != nil {
		return nil, e
	}
	svg := fmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="%g %g %g %g">%s</svg>`, view.X, view.Y, view.W, view.H, body)
	return &pptx.ImageProps{PositionProps: pos(b), ObjectNameProps: pptx.ObjectNameProps{ObjectName: id}, DataOrPathProps: pptx.DataOrPathProps{Data: primitiveDataURI("image/svg+xml", []byte(svg))}, SVGFallbackData: primitiveDataURI("image/png", fallback), AltText: "Frozen geographic dot field; data SHA256=" + intakeGeoDataSHA256}, nil
}
